for (const config of expected) {
 const matches = input.filter(p=>(p.sourceId||p.source_id)===config.sourceId);
 const p=matches[0]||{};
 const items=Array.isArray(p.menuItems)?p.menuItems:[];
 const good=matches.length===1 && p.ok!==false && !['failed','skipped'].includes(p.status) && items.length>0 && items.every(i=>i.source_id===config.sourceId && i.item_uid && i.menu_date===config.menuDate);
