 sources.push(record);
 if(good) parents.push(p);
}
const runId=expected[0]?.runId;
if(!runId || expected.some(c=>c.runId!==runId)) throw new Error('AUDIT_INCONSISTENT_RUN_ID');
return [{json:{run_id:runId,runId,startedAt:expected[0].startedAt,menuDate:expected[0].menuDate,sourceCount:expected.length,sources,parents,stage:'audit_start',itemCount:parents.reduce((n,p)=>n+p.menuItems.length,0)}}];

function clean(value, fallback = '') {
  if (value === null || value === undefined) return fallback;
  return String(value)
    .replace(/[\u0000-\u001F\u007F]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function normalizeCategory(value) {
  const allowed = ['soup', 'main', 'pizza', 'special', 'side', 'dessert', 'drink', 'unknown'];
  const category = clean(value, 'main').toLowerCase();
  return allowed.includes(category) ? category : 'main';
}

const parents = $('Code - Prepare Run Audit').first().json.parents;
const output = [];

for (const parent of parents) {
  const items = Array.isArray(parent.menuItems) ? parent.menuItems : [];
  for (const raw of items) {
    const price = raw.price_eur === null || raw.price_eur === undefined || raw.price_eur === ''
      ? null
      : Number(raw.price_eur);

    output.push({
      json: {
        item_uid: clean(raw.item_uid),
        source_id: clean(raw.source_id),
        source_name: clean(raw.source_name),
        source_type: clean(raw.source_type),
        source_url: clean(raw.source_url),
        menu_date: clean(raw.menu_date),
        menu_code: clean(raw.menu_code),
        category: normalizeCategory(raw.category),
        title: clean(raw.title),
        description: clean(raw.description),
        price_eur: Number.isFinite(price) ? price : null,
        currency: clean(raw.currency, 'EUR') || 'EUR',
        allergens: Array.isArray(raw.allergens) ? raw.allergens.map(v => clean(v)).filter(Boolean) : [],
        raw_text: clean(raw.raw_text),
        parsed_at: clean(raw.parsed_at, new Date().toISOString()),
        run_id: clean(raw.run_id || parent.run_id || parent.runId, `manual-${Date.now()}`),
        ingestion_status: 'ready_for_db',
      }
    });
  }
}

return output.length ? output.map(i=>({json:{...i.json,itemCount:1}})) : [{json:{_auditOnly:true,itemCount:0}}];

