console.log(JSON.stringify({event:'restaurant_transactions_prepared',runId:audit.run_id,transactions:output.map(i=>({sourceId:i.json.source_id,items:i.json.itemCount}))}));
return output.length?output:[{json:{_auditOnly:true,itemCount:0,run_id:audit.run_id}}];

