const audit=$('Code - Prepare Run Audit').first().json;
const planned=$('Code - Expand Items').all().map(i=>i.json).filter(i=>!i._auditOnly);
const raw=$input.all().map(i=>i.json).filter(i=>!i._auditOnly);
const acknowledgements=new Set(raw.filter(r=>r.db_ok===true&&r.run_id===audit.run_id).map(r=>r.item_uid));
const dbErrors=raw.filter(r=>r.error||r.errorMessage||r.errorDescription);
