 if(s.skipped===true && s.status==='skipped') return {...s,ok:true,expectedItems:0,writtenItems:0,missingWrites:0,errorMessage:null};
 const expected=new Set(planned.filter(i=>i.source_id===s.sourceId).map(i=>i.item_uid));
 const written=[...expected].filter(id=>acknowledgements.has(id)).length;
