function describeError(value) {
 const fields=[], seen=new Set();
 const scalarKeys=['message','description','errorMessage','errorDescription','detail','hint','code','sqlState','severity','schema','table','column','constraint','position','name'];
 function clean(v) { return String(v).replace(/(postgres(?:ql)?:\/\/[^:\s/]+:)[^@\s]+@/gi,'$1[REDACTED]@').replace(/(password\s*[=:]\s*)[^\s;]+/gi,'$1[REDACTED]').slice(0,1800); }
 function visit(v,path,depth) {
  if(v===null||v===undefined||depth>6)return;
  if(typeof v==='string'||typeof v==='number'){if(String(v).trim())fields.push({field:path||'error',value:clean(v)});return;}
  if(typeof v!=='object'||seen.has(v))return;
  seen.add(v);
  if(Array.isArray(v)){v.slice(0,5).forEach((e,i)=>visit(e,path+'['+i+']',depth+1));return;}
  for(const key of scalarKeys)if(v[key]!==undefined)visit(v[key],path?path+'.'+key:key,depth+1);
  for(const key of ['error','cause','errors','details'])if(v[key]!==undefined)visit(v[key],path?path+'.'+key:key,depth+1);
 }
 visit(value,'',0);
 const unique=[...new Map(fields.map(x=>[x.field+'='+x.value,x])).values()];
 return {message:unique.length?unique.map(x=>x.field+': '+x.value).join(' | ').slice(0,5000):'No readable error text; inspect input keys: '+Object.keys(value||{}).join(', '),fields:unique.slice(0,25)};
}
return $input.all().map(({json: item}) => {


const source = item.sourceId || item.source_id || item.sourceName || item.source_name || 'unknown-source';
const stage = item.stage || item.errorStage || item.status || item.errorCode || 'workflow';
const errorValue = item.errorMessage || item.error_message || item.error || item.message || item.errorDescription || item.description || item.debugMessage || 'No detailed error message from previous node';
const errorMessage = typeof errorValue === 'string' ? errorValue : describeError(errorValue).message;
const runId = item.run_id || item.runId || item.runID || item.executionId || item.importRunId || 'missing-run-id';
const itemCount = item.itemCount !== undefined ? item.itemCount : (Array.isArray(item.menuItems) ? item.menuItems.length : 'unknown');
const debug = item.debugDayLines || item.debugLines || item.debugPreview || item.availableBlocks || item.menuItems || '';

return {
